/* HEXA BATTLEGROUNDS upgrade3 — PART 1 OF 15. For databases that already ran supabase/upgrade-2 (open world); Run in order. Safe to re-run. */ alter table mission_instances add column if not exists revealed jsonb not null default '{}'::jsonb; create or replace function _defaults() returns jsonb language sql immutable as $$ select jsonb_build_object( 'pts_standard', 100, 'pts_hard', 150, 'pts_battle', 125, 'pts_airdrop', 75, 'pts_relay_bonus', 25, 'pts_relocation', 40, 'pen_recovery', 40, 'finale_max', 300, 'finale_entry_max', 200, 'finale_exchange_max', 200, 'hp_max', 100, 'hp_respawn', 50, 'dmg_fail', 10, 'dmg_zone', 15, 'shield_max', 60, 'shuttle_seconds', 10, 'roles_seconds', 15, 'bus_size', 3, 'arena_size', 15, 'attack_cooldown', 90, 'protect_seconds', 120, 'recovery_seconds', 120, 'zone_warning', 60, 'airdrop_window', 180, 'airdrop_interval', 0, 'intel_fallback', 90, 'relay_chance', 20, 'hint_cost', 0, 'alliance_minutes', 10, 'alliance_cost', 10, 'chat_limit', 6, 'drop_seconds', 8, 'visit_missions', 2, 'zone_auto', 0, 'zone_schedule', '20,40,55,70,85', 'sync_seconds', 0, 'auto_pacing', 0, 'phase_schedule', '2,12,30,50', 'duel_phase', 2, 'mission_time_pct', 100, 'pin_length', 6, 'move_speed', 25, 'loc_radius', 35, 'engage_range', 60, 'zone_tick_seconds', 6, 'zone_tick_damage', 4, 'red_interval', 0, 'red_warning', 20, 'red_damage', 30, 'red_radius', 80 ) || jsonb_build_object( 'reveal_pct', 50 ) $$; create or replace function _loc_xy(p_loc text) returns float8[] language sql stable as $$ select array[x::float8, y::float8] from locations where id = p_loc $$; create or replace function _team_xy(t teams) returns float8[] language plpgsql stable as $$ declare d float8[]; p float8; begin if t.state = 'traveling' and t.travel_to is not null and t.travel_arrive_at is not null then d := _loc_xy(t.travel_to); if t.travel_fx is not null and d is not null then p := least(1, greatest(0, extract(epoch from now() - t.travel_started_at) / greatest(0.001, extract(epoch from t.travel_arrive_at - t.travel_started_at)))); return array[t.travel_fx + (d[1] - t.travel_fx) * p, t.travel_fy + (d[2] - t.travel_fy) * p]; end if; end if; if t.pos_x is not null then return array[t.pos_x::float8, t.pos_y::float8]; end if; return coalesce(_loc_xy(t.location_id), array[0.5, 0.93]); end $$;
